// Generate a random error code (bounded to a small range to hit known codes)
int code = (int)(*FUZZ_PARAM(unsigned int) % 50) - 10; // includes some negatives and out-of-range
const char *s = mosqpp::strerror(code);
// API guarantees returning a valid string; assert non-null
FUZZ_ASSERT(s != NULL, "mosqpp::strerror must return a non-null string");

// Generate a connack code (0..10 typical range, include some out-of-range too)
int code = (int)(*FUZZ_PARAM(unsigned int) % 20);
const char *s = mosqpp::connack_string(code);
FUZZ_ASSERT(s != NULL, "mosqpp::connack_string must return a non-null string");

// Prepare a UTF-8 subscription/topic string
std::string topic = FUZZ_PARAM_STR();
if (topic.size() > 256) topic.resize(256);
// Ensure valid UTF-8 per wrapper contract; bail if invalid
int vrc = mosqpp::validate_utf8(topic.c_str(), (int)topic.size());
if (vrc != 0) { FUZZ_BAIL(); }

// Allocate a persistent holder for the library to fill: char ** stored behind a heap char **
char **holder = (char **)malloc(sizeof(char *));
if (!holder) { FUZZ_BAIL(); }
*holder = NULL; // required initialisation
char ***topics = &holder; // type: char *** as required by API
int count = 0;

int rc = mosqpp::sub_topic_tokenise(topic.c_str(), topics, &count);
if (rc != 0 || count <= 0 || *holder == NULL) {
    // On failure or empty result, release holder and bail to avoid leaking an unusable handle
    free(holder);
    FUZZ_BAIL();
}

// Expose holder as an opaque handle to be consumed by sub_topic_tokens_free
void *topics_handle = (void *)holder;
FUZZ_SET_ATTR_INT(topics_handle, "count", count);
FUZZ_SET_ATTR_STR(topics_handle, "type", "sub_tokens");

// Validate that the handle looks like one produced by sub_topic_tokenise
const char *ty = FUZZ_GET_ATTR_STR(topics_handle, "type");
int count = FUZZ_GET_ATTR_INT(topics_handle, "count");
if (!ty || ty[0] == '\0' || count <= 0) { FUZZ_BAIL(); }

// Recover the heap-allocated holder
char **holder = (char **)topics_handle;
if (holder == NULL) { FUZZ_BAIL(); }

// Free with the wrapper; pass address of holder as a char ***
char ***topics_ptr = &holder;
int rc = mosqpp::sub_topic_tokens_free(topics_ptr, count);
// Free our holder regardless; the API frees the array and sets *holder to NULL, but not the holder itself
free(holder);

if (rc != 0) { FUZZ_BAIL(); }

int maj=0, min=0, rev=0;
int ver = mosqpp::lib_version(&maj, &min, &rev);
// Basic property: returned pointers were written; combined version non-negative
FUZZ_ASSERT(maj >= 0 && min >= 0 && rev >= 0, "lib_version wrote non-negative components");
FUZZ_ASSERT(ver >= 0, "lib_version returned non-negative combined version");

int rc = mosqpp::lib_init();
// Track init count globally for pairing with cleanup
int cnt = FUZZ_GET_ATTR_INT_GLOBAL("mosqpp_lib_init_count");
FUZZ_SET_ATTR_INT_GLOBAL("mosqpp_lib_init_count", cnt + 1);
// rc may be success or specific errors; no assertion beyond non-crash
(void)rc;

// Enforce pairing: only cleanup if we've initialised at least once
int cnt = FUZZ_GET_ATTR_INT_GLOBAL("mosqpp_lib_init_count");
if (cnt <= 0) { FUZZ_BAIL(); }
int rc = mosqpp::lib_cleanup();
FUZZ_SET_ATTR_INT_GLOBAL("mosqpp_lib_init_count", cnt - 1);
(void)rc;

// Create subscription and topic strings; enforce UTF-8 validity
std::string sub = FUZZ_PARAM_STR();
std::string topic = FUZZ_PARAM_STR();
if (sub.size() > 256) sub.resize(256);
if (topic.size() > 256) topic.resize(256);
if (mosqpp::validate_utf8(sub.c_str(), (int)sub.size()) != 0) { FUZZ_BAIL(); }
if (mosqpp::validate_utf8(topic.c_str(), (int)topic.size()) != 0) { FUZZ_BAIL(); }

bool match = false;
int rc = mosqpp::topic_matches_sub(sub.c_str(), topic.c_str(), &match);
// rc==0 typically success; do not assert on value other than non-crash
(void)rc;

// Randomly choose to test NULL with len=0 or a real buffer
unsigned int mode = *FUZZ_PARAM(unsigned int) % 3;
if (mode == 0) {
    int rc = mosqpp::validate_utf8(NULL, 0);
    FUZZ_ASSERT(rc == 0, "NULL with len=0 should be valid per API");
} else {
    std::string s = FUZZ_PARAM_STR();
    if (s.size() > 512) s.resize(512);
    int len_mode = (int)(*FUZZ_PARAM(unsigned int) % 2);
    int len = len_mode ? (int)s.size() : (int)(*FUZZ_PARAM(unsigned int) % 1024);
    if (len < 0) len = 0;
    if (len > 65536) len = 65536;
    // Call validator; accept any return without assertion beyond non-crash
    (void)mosqpp::validate_utf8(s.c_str(), len);
}

// Decide whether to pass a NULL id or a non-NULL UTF-8 id
unsigned int pick = *FUZZ_PARAM(unsigned int);
bool use_null_id = (pick & 1) != 0;
bool clean_session = true; // ensure clean_session is true when id is NULL
const char *id_ptr = NULL;
if (!use_null_id) {
    std::string id = FUZZ_PARAM_STR();
    if (id.size() > 23) id.resize(23); // typical client id limits
    // Ensure valid UTF-8 for id
    if (mosqpp::validate_utf8(id.c_str(), (int)id.size()) != 0) { FUZZ_BAIL(); }
    id_ptr = id.c_str();
    clean_session = ((pick >> 1) & 1) != 0; // random bool when id is non-NULL
}

mosqpp::mosquittopp *client = new mosqpp::mosquittopp(id_ptr, clean_session);
FUZZ_ASSERT(client != NULL, "mosquittopp constructor returned non-null");
// Track connection/thread state for safe later use
FUZZ_SET_ATTR_INT(client, "connected", 0);
FUZZ_SET_ATTR_INT(client, "loop_thread", 0);
FUZZ_SET_ATTR_INT(client, "will_set", 0);

// Ensure background loop thread is not running to avoid races per requirement
int loop_thread = FUZZ_GET_ATTR_INT(client, "loop_thread");
if (loop_thread != 0) { FUZZ_BAIL(); }
// Destroy the client; runtime will not reuse after this
delete client;

// Pick id NULL/non-NULL with required clean_session when NULL
unsigned int pick = *FUZZ_PARAM(unsigned int);
bool use_null_id = (pick & 1) != 0;
bool clean_session = true;
const char *id_ptr = NULL;
if (!use_null_id) {
    std::string id = FUZZ_PARAM_STR();
    if (id.size() > 23) id.resize(23);
    if (mosqpp::validate_utf8(id.c_str(), (int)id.size()) != 0) { FUZZ_BAIL(); }
    id_ptr = id.c_str();
    clean_session = ((pick >> 1) & 1) != 0;
}
int rc = client->reinitialise(id_ptr, clean_session);
(void)rc;
// After reinitialise, assume disconnected
FUZZ_SET_ATTR_INT(client, "connected", 0);
FUZZ_SET_ATTR_INT(client, "will_set", 0);

int fd = client->socket();
// fd may be -1 if not connected/initialised; assert only non-crash
(void)fd;

// Must be called before connect; enforce by checking our connection attribute
if (FUZZ_GET_ATTR_INT(client, "connected") != 0) { FUZZ_BAIL(); }

std::string topic = FUZZ_PARAM_STR();
if (topic.size() > 256) topic.resize(256);
if (mosqpp::validate_utf8(topic.c_str(), (int)topic.size()) != 0) { FUZZ_BAIL(); }

std::string payload = FUZZ_PARAM_STR();
if (payload.size() > 1024) payload.resize(1024);
int payloadlen = (int)(*FUZZ_PARAM(unsigned int) % (payload.size() + 1));
int qos = (int)(*FUZZ_PARAM(unsigned int) % 3);
bool retain = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;

int rc = client->will_set(topic.c_str(), payloadlen, payload.data(), qos, retain);
(void)rc;
FUZZ_SET_ATTR_INT(client, "will_set", 1);

// Must be called before connect; enforce by attribute
if (FUZZ_GET_ATTR_INT(client, "connected") != 0) { FUZZ_BAIL(); }
int rc = client->will_clear();
(void)rc;
FUZZ_SET_ATTR_INT(client, "will_set", 0);

// Must be called before connect; enforce by attribute
if (FUZZ_GET_ATTR_INT(client, "connected") != 0) { FUZZ_BAIL(); }

unsigned int pick = *FUZZ_PARAM(unsigned int);
bool use_null_user = (pick & 1) != 0;
const char *user = NULL;
const char *pass = NULL;
std::string u = FUZZ_PARAM_STR(); if (u.size() > 64) u.resize(64);
std::string p = FUZZ_PARAM_STR(); if (p.size() > 64) p.resize(64);
if (!use_null_user) { user = u.c_str(); pass = p.c_str(); }
int rc = client->username_pw_set(user, pass);
(void)rc;

// Enforce: must only be called after an initial connect/connect_async has been made
int ever = FUZZ_GET_ATTR_INT(client, "ever_connected");
if (ever == 0) { FUZZ_BAIL(); }

int rc = client->reconnect();
// If reconnect succeeds, mark connected; otherwise leave state unchanged
if (rc == 0) {
    FUZZ_SET_ATTR_INT(client, "connected", 1);
}
// Validation: we enforce prior connection attempt via attribute and update connection state on success.

// Enforce: must only be called after an initial connect/connect_async and using threaded loop
int ever = FUZZ_GET_ATTR_INT(client, "ever_connected");
int loop_thread = FUZZ_GET_ATTR_INT(client, "loop_thread");
if (ever == 0 || loop_thread == 0) { FUZZ_BAIL(); }

int rc = client->reconnect_async();
if (rc == 0) {
    // Async reconnect initiated; mark as connecting (not fully connected yet)
    FUZZ_SET_ATTR_INT(client, "connected", 0);
}
// Validation: require prior connect attempt and active loop thread per API guidance.

// Enforce: client should be connected
if (FUZZ_GET_ATTR_INT(client, "connected") == 0) { FUZZ_BAIL(); }

int rc = client->disconnect();
(void)rc;
// After requesting disconnect, mark as not connected
FUZZ_SET_ATTR_INT(client, "connected", 0);
// Validation: we only call when connected and update state to disconnected afterwards.

// Enforce: client must be connected to publish
if (FUZZ_GET_ATTR_INT(client, "connected") == 0) { FUZZ_BAIL(); }

// Topic must be valid UTF-8 and not a subscription filter
std::string topic = FUZZ_PARAM_STR();
if (topic.size() > 128) topic.resize(128);
if (mosqpp::validate_utf8(topic.c_str(), (int)topic.size()) != 0) { FUZZ_BAIL(); }

// Payload generation within MQTT size limits
std::string payload = FUZZ_PARAM_STR();
if (payload.size() > 1024) payload.resize(1024);
int payloadlen = (int)(*FUZZ_PARAM(unsigned int) % (payload.size() + 1));
int qos = (int)(*FUZZ_PARAM(unsigned int) % 3);
bool retain = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;

// mid may be NULL or provided
int mid_storage = 0;
int *mid_ptr = ((*FUZZ_PARAM(unsigned int)) & 1) ? &mid_storage : NULL;

int rc = client->publish(mid_ptr, topic.c_str(), payloadlen, payloadlen ? payload.data() : NULL, qos, retain);
(void)rc;
// Validation: enforce connection, UTF-8 topic, bounds on payload/qos; safe mid handling.

// Enforce: client must be connected
if (FUZZ_GET_ATTR_INT(client, "connected") == 0) { FUZZ_BAIL(); }

std::string sub = FUZZ_PARAM_STR();
if (sub.size() > 128) sub.resize(128);
if (mosqpp::validate_utf8(sub.c_str(), (int)sub.size()) != 0) { FUZZ_BAIL(); }
int qos = (int)(*FUZZ_PARAM(unsigned int) % 3);

int mid_storage = 0;
int *mid_ptr = ((*FUZZ_PARAM(unsigned int)) & 1) ? &mid_storage : NULL;

int rc = client->subscribe(mid_ptr, sub.c_str(), qos);
(void)rc;
// Validation: enforce connection and UTF-8; qos in [0,2]; mid optional and valid.

// Enforce: client must be connected
if (FUZZ_GET_ATTR_INT(client, "connected") == 0) { FUZZ_BAIL(); }

std::string sub = FUZZ_PARAM_STR();
if (sub.size() > 128) sub.resize(128);
if (mosqpp::validate_utf8(sub.c_str(), (int)sub.size()) != 0) { FUZZ_BAIL(); }

int mid_storage = 0;
int *mid_ptr = ((*FUZZ_PARAM(unsigned int)) & 1) ? &mid_storage : NULL;

int rc = client->unsubscribe(mid_ptr, sub.c_str());
(void)rc;
// Validation: enforce connection and UTF-8; mid optional and valid.

// Choose valid delays: max >= delay
unsigned int delay = (unsigned int)(*FUZZ_PARAM(unsigned int) % 10) + 1; // 1..10s
unsigned int delay_max = delay + (unsigned int)(*FUZZ_PARAM(unsigned int) % 20); // >= delay
bool exp_backoff = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;

client->reconnect_delay_set(delay, delay_max, exp_backoff);
// Validation: parameters constrained so max >= delay; called regardless of connection state.

unsigned int max_inflight = (unsigned int)(*FUZZ_PARAM(unsigned int) % 1000); // keep small
int rc = client->max_inflight_messages_set(max_inflight);
(void)rc;
// Validation: non-negative value; no further constraints.

unsigned int retry = (unsigned int)(*FUZZ_PARAM(unsigned int) % 10);
client->message_retry_set(retry);
// Validation: API is no-op; ensure non-crash and small argument.

// Provide a stable pointer with safe lifetime: use the client itself as userdata
void *userdata = (void *)client;
client->user_data_set(userdata);
// Track for downstream checks if desired
FUZZ_SET_ATTR_PTR(client, "userdata", userdata);
// Validation: pointer is non-null and lifetime tied to client; safe per API.

// Must be called before connecting
if (FUZZ_GET_ATTR_INT(client, "connected") != 0) { FUZZ_BAIL(); }

// At least one of cafile or capath must be non-NULL
const char *cafile = NULL;
const char *capath = NULL;
const char *certfile = NULL;
const char *keyfile = NULL;

unsigned int pick = *FUZZ_PARAM(unsigned int);
bool use_cafile = (pick & 1) != 0;
bool use_capath = (pick & 2) != 0;
if (!use_cafile && !use_capath) { use_cafile = true; }
if (use_cafile) cafile = FUZZ_PARAM_FILENAME();
if (use_capath) capath = FUZZ_PARAM_FILENAME();

// Either both certfile and keyfile are NULL, or both non-NULL
