    keyfile  = FUZZ_PARAM_FILENAME();
}

// No password callback by default
int rc = client->tls_set(cafile, capath, certfile, keyfile, NULL);
(void)rc;
// Validation: pre-connect enforcement; cafile/capath constraint; cert/key consistency.

// Must be called before connecting
if (FUZZ_GET_ATTR_INT(client, "connected") != 0) { FUZZ_BAIL(); }

int cert_reqs = (int)(*FUZZ_PARAM(unsigned int) % 2); // 0 or 1
// Randomly choose to pass a tls_version or ciphers string, keep them short
const char *tls_version = NULL;
const char *ciphers = NULL;
unsigned int pick = *FUZZ_PARAM(unsigned int);
if (pick & 1) {
    std::string v = FUZZ_PARAM_STR();
    if (v.size() > 8) v.resize(8);
    tls_version = v.c_str();
}
if (pick & 2) {
    std::string c = FUZZ_PARAM_STR();
    if (c.size() > 32) c.resize(32);
    ciphers = c.c_str();
}
int rc = client->tls_opts_set(cert_reqs, tls_version, ciphers);
(void)rc;
// Validation: pre-connect enforced; cert_reqs constrained to known values; optional strings limited.

// Must be called before connecting
if (FUZZ_GET_ATTR_INT(client, "connected") != 0) { FUZZ_BAIL(); }

bool value = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
int rc = client->tls_insecure_set(value);
(void)rc;
// Validation: pre-connect enforced; boolean chosen randomly.

// Must be called before connecting and not with certificate-based TLS simultaneously (we don't set certs here)
if (FUZZ_GET_ATTR_INT(client, "connected") != 0) { FUZZ_BAIL(); }

// Generate a hex PSK string with even length (2..64)
static const char hex_digits[] = "0123456789abcdef";
unsigned int nbytes = (unsigned int)(*FUZZ_PARAM(unsigned int) % 32) + 1; // 1..32 bytes -> 2..64 hex chars
std::string psk; psk.reserve(nbytes * 2);
for (unsigned int i = 0; i < nbytes * 2; ++i) {
    unsigned int idx = (unsigned int)(*FUZZ_PARAM(unsigned int) % 16);
    psk.push_back(hex_digits[idx]);
}

// Identity must be non-NULL and valid UTF-8
std::string identity = FUZZ_PARAM_STR();
if (identity.size() > 64) identity.resize(64);
if (mosqpp::validate_utf8(identity.c_str(), (int)identity.size()) != 0) { FUZZ_BAIL(); }

// Optionally pass a ciphers string
