int timeout = 0;
int max_packets = 1;
int rc = client->loop(timeout, max_packets);
(void)rc;
// Validation: non-blocking invocation; safe regardless of connection (may return error if not connected).

int rc = client->loop_misc();
(void)rc;
// Validation: safe periodic call; no blocking; acceptable even if not connected.

