if (FUZZ_GET_ATTR_INT(client, "loop_thread") != 0) { FUZZ_BAIL(); }

int rc = client->loop_start();
if (rc != 0) { FUZZ_BAIL(); }
// Mark background thread as running for safe pairing with loop_stop/destructor
FUZZ_SET_ATTR_INT(client, "loop_thread", 1);
// Validation: we prevent double-start and record thread state for later teardown.

