// Thread has stopped; update attribute for safe destruction later
FUZZ_SET_ATTR_INT(client, "loop_thread", 0);
// Validation: we enforce active thread precondition and ensure attribute reflects stopped state.

// Query write readiness; valid after initialisation
bool w = client->want_write();
(void)w;
// Validation: non-crashing query; client remains owned and returned.

// Inform library about external threading usage (not using loop_start here)
bool threaded = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
int rc = client->threaded_set(threaded);
(void)rc;
// Track hint for downstream diagnostics
FUZZ_SET_ATTR_INT(client, "threaded", threaded ? 1 : 0);
// Validation: simple, non-blocking setter; attribute records intent.

// Must be called before connect
if (FUZZ_GET_ATTR_INT(client, "connected") != 0) { FUZZ_BAIL(); }

// Host non-NULL; keep short
std::string host_s = FUZZ_PARAM_STR();
if (host_s.size() == 0) { host_s = "localhost"; }
if (host_s.size() > 128) host_s.resize(128);
